// Rebuild checked-in offline Leaflet code after an intentionally reviewed upgrade.
const fs = require("node:fs");
const path = require("node:path");
const root = path.resolve(__dirname, "../..");
for (const app of ["agent-app", "delivery-app"]) {
  const source = path.join(root, app, "node_modules/leaflet");
  const version = JSON.parse(fs.readFileSync(path.join(source, "package.json"), "utf8")).version;
  if (version !== "1.9.4") throw new Error(`Review Leaflet version before bundling: ${version}`);
  const license = fs.readFileSync(path.join(source, "LICENSE"), "utf8");
  const js = fs.readFileSync(path.join(source, "dist/leaflet.js"), "utf8").replace(/\/\/# sourceMappingURL=.*$/m, "");
  const css = fs.readFileSync(path.join(source, "dist/leaflet.css"), "utf8");
  const target = path.join(root, app, "src/components/maps/vendor");
  fs.mkdirSync(target, { recursive: true });
  fs.writeFileSync(path.join(target, "leaflet.ts"), `// Generated by agent-app/scripts/bundle-map-engine.cjs. Leaflet ${version}.\nexport const leafletJs = ${JSON.stringify(js)};\nexport const leafletCss = ${JSON.stringify(css)};\nexport const leafletLicense = ${JSON.stringify(license)};\n`);
  fs.writeFileSync(path.join(target, "LICENSE.txt"), license);
}
